253	export function useDeleteMemo() {
254	  const queryClient = useQueryClient();
255	
256	  return useMutation({
257	    mutationFn: async (name: string) => {
258	      await memoServiceClient.deleteMemo({ name });
259	      return name;
260	    },
261	    onSuccess: (name) => {
262	      // Remove from cache
263	      queryClient.removeQueries({ queryKey: memoKeys.detail(name) });
264	      // Invalidate lists
265	      queryClient.invalidateQueries({ queryKey: memoKeys.lists() });
266	      // Invalidate user stats
267	      queryClient.invalidateQueries({ queryKey: userKeys.stats() });
268	    },
269	  });
270	}
271	
272	export function useMemoComments(name: string, options?: { enabled?: boolean; pageSize?: number }) {
273	  return useQuery({
274	    queryKey: [...memoKeys.comments(name), options?.pageSize ?? 0],
275	    queryFn: async () => {
276	      const response = await memoServiceClient.listMemoComments(
277	        create(ListMemoCommentsRequestSchema, {
278	          name,
279	          pageSize: options?.pageSize ?? 0,
280	        }),
281	      );
282	      return response;
283	    },
284	    enabled: options?.enabled ?? true,
285	    staleTime: 1000 * 60, // 1 minute
286	  });
287	}
288	
289	// useInfiniteMemoComments paginates through every comment via nextPageToken, instead of
290	// stopping at the server's default page size (the cause of comments being truncated to 10).
291	export function useInfiniteMemoComments(name: string, options?: { enabled?: boolean; pageSize?: number }) {
292	  const pageSize = options?.pageSize ?? DEFAULT_LIST_MEMOS_PAGE_SIZE;
293	  return useInfiniteQuery({
294	    queryKey: [...memoKeys.comments(name), "infinite", pageSize],
295	    queryFn: async ({ pageParam }) => {
296	      const response = await memoServiceClient.listMemoComments(
297	        create(ListMemoCommentsRequestSchema, {
298	          name,
299	          pageSize,
300	          pageToken: pageParam || "",
301	        }),
302	      );
303	      return response;
304	    },
305	    initialPageParam: "",
306	    getNextPageParam: (lastPage) => lastPage.nextPageToken || undefined,
307	    select: (data) => data.pages.flatMap((page) => page.memos),
308	    enabled: options?.enabled ?? true,
309	    staleTime: 1000 * 60, // 1 minute
310	  });
311	}
